def parse_assignments(items: List[str]) -> Dict[str, int]:
    """Parse `--set key=value` pairs into integer overrides."""
    out: Dict[str, int] = {}
    for item in items:
        key, sep, raw = item.partition("=")
        if not sep:
            raise ValueError(f"expected key=value, got {item!r}")
        out[key.strip()] = int(raw)
    return out
